css:
/* The report is always Arabic and RTL - there is no language switch. The
   tables are laid out right-to-left, so the first column of the markup (Employee ID) is
   the far-right one and the last (Total Hours) the far-left one.

   Fonts are bundled with the app and inlined by pow_font_faces(); wkhtmltopdf has no
   network on the print server. The fallbacks after Readex Pro are not a hedge: without an
   Arabic-capable face every Arabic word draws as an empty box. */

/* Landscape: 31 day columns plus 5 fixed ones do not fit portrait. Frappe forwards
   these declarations from .print-format to wkhtmltopdf. */
.print-format {
	orientation: landscape;
	page-size: A4;
	margin-left: 6mm;
	margin-right: 6mm;
	margin-top: 8mm;
	margin-bottom: 8mm;
}

.pow-att, .pow-att * { font-family: 'Readex Pro', 'Noto Sans Arabic', 'DejaVu Sans', sans-serif; }
.pow-att { font-size: 8px; direction: rtl; }
/* A value that is Latin by rule (Employee ID, the Sale Item line) keeps its own order and
   direction inside the RTL page. Without this the hyphens and digits of HR-EMP-03541 are
   reordered by the bidi algorithm. */
.pow-att .en { direction: ltr; unicode-bidi: embed; }
/* A value that may be Arabic or English (client, project, employee name) takes its
   direction from its own first strong character. */
.pow-att .val { unicode-bidi: plaintext; }
/* logo, title and Report Period on one line - a table rather than flex,
   because wkhtmltopdf does not lay flex out reliably. The table is RTL, so the cell that
   comes first (pow-hd-left, the logo and title) sits on the right. */
.pow-hd { width: 100%; border-collapse: collapse; margin-bottom: 4px; direction: rtl; }
.pow-hd td { border: none; padding: 0; vertical-align: middle; }
.pow-hd-left { text-align: right; }
/* width 1% makes this cell take only what its text needs, leaving the rest to the other
   cell - without it the two share the width and the period wraps. */
.pow-hd-right { text-align: left; font-size: 8px; white-space: nowrap; width: 1%; }
.pow-logo { height: 44px; vertical-align: middle; }
.pow-hd-txt { display: inline-block; vertical-align: middle; margin-right: 8px; }
.pow-title { font-size: 13px; font-weight: 700; }
.pow-meta { font-size: 7.5px; margin-bottom: 4px; }
.pow-meta span { margin-left: 10px; }
.pow-legend { font-size: 7px; background: #f3f3f3; padding: 3px 5px; margin-bottom: 5px; }

/* One header bar per Sale Item, carrying the item type(s) after the code. */
.pow-grp { width: 100%; background: #eaeaea; font-size: 8px; margin-top: 7px; border-collapse: collapse; direction: rtl; }
.pow-grp td { padding: 3px 5px; border: none; }
.pow-grp-item { text-align: right; }
.pow-grp-count { text-align: left; opacity: 0.85; white-space: nowrap; width: 90px; }

.pow-grid { width: 100%; border-collapse: collapse; table-layout: fixed; direction: rtl; }
/* Repeat the header on every page but keep wkhtmltopdf from overlapping tall rows. */
.pow-grid thead { display: table-row-group; }
.pow-grid th, .pow-grid td {
	border: 1px solid #bbb; padding: 1px 0; font-size: 6.5px;
	text-align: center; vertical-align: middle;
	/* Weekday names and dates must stay on one line; only the two label columns and
	   the totals headers are allowed to wrap, and then only at spaces. */
	white-space: nowrap;
}
.pow-grid th { background: #f7f7f7; font-weight: 600; }
.pow-grid .c-id, .pow-grid .c-name { text-align: right; padding-right: 3px; }
.pow-grid .c-id { width: 58px; white-space: normal; }
.pow-grid .c-name { width: 104px; white-space: normal; }
.pow-grid .c-day { width: 24px; }
.pow-grid .c-num { width: 32px; white-space: normal; }
/* "Working Days" and "Days Off" both wrapped inside 32px, which ran the two
   headings together. Each of the three totals columns now carries its own width, wide
   enough for its own heading. */
.pow-grid .c-worked-days { width: 46px; }
.pow-grid .c-days-off { width: 38px; }
.pow-grid .c-total-hours { width: 38px; }
/* Weekend columns shaded, as the Attendance Amendment preview does. */
.pow-grid .c-wknd { background: #f0f4f8; }
.pow-grid .pow-total td { font-weight: 700; background: #f7f7f7; }
.empty { text-align: center; color: #777; padding: 6px; font-style: italic; }
